// План specs/rtl-jobs.md 1.1–1.3 (кейсы .qa/tests/rtl-jobs/RTL-01…RTL-03). Admin, компания «test», десктоп 1440×900. Только просмотр:
// New Job не сохраняется, Job Details только открывается (автосохранение — ничего не трогаем), send-sms перехватывается.
// Проверка — по положению на экране (центры элементов по X): HE — справа налево, EN — слева направо.
// Job Details — JOB-0094 в «test» (id из multi-business/business-helpers.ts).
// Не сверено с сайтом при записи: вкладки Job Details — role=tab; заголовок «כתובת השירות» в Job Details (HE).
import { test, expect, Page } from '@playwright/test';
import {
  ADMIN_STATE, Lang, blockSmsSending, centerX, centers, expectNoSmsSent, isDecreasing, isIncreasing, openJobsList, restoreCompany, useLang,
} from '../job-dates/job-dates-helpers';
import { DATA } from '../multi-business/business-helpers';

test.use({ storageState: ADMIN_STATE });

const L = {
  en: {
    jobInfo: 'Job Info', clientDetails: 'Client Details', serviceLocation: 'Service Location', clientName: 'Client Name',
    details: 'Details', equipment: 'Equipment',
  },
  he: {
    jobInfo: 'פרטי עבודה', clientDetails: 'פרטי לקוח', serviceLocation: 'כתובת השירות', clientName: 'שם הלקוח',
    details: 'פרטים', equipment: 'ציוד', jobNumberCol: /^\s*מספר עבודה\s*$/,
  },
} as const;

const heading = (page: Page, text: string) => page.locator('main').getByText(text, { exact: true }).first();

/** Ожидаемый порядок по X для элементов в порядке DOM: HE — убывает (первый справа), EN — возрастает. */
function expectOrder(xs: number[], lang: Lang, what: string) {
  if (lang === 'he') expect(isDecreasing(xs), `${what} (HE): справа налево, x=${xs.map(Math.round).join(',')}`).toBe(true);
  else expect(isIncreasing(xs), `${what} (EN): слева направо, x=${xs.map(Math.round).join(',')}`).toBe(true);
}

/** «Client Details» и «Service Location»: HE — клиент справа; EN — клиент слева. */
async function expectColumns(page: Page, lang: Lang) {
  const client = await centerX(heading(page, L[lang].clientDetails));
  const location = await centerX(heading(page, L[lang].serviceLocation));
  if (lang === 'he') expect(client, 'HE: «פרטי לקוח» правее «כתובת השירות»').toBeGreaterThan(location);
  else expect(client, 'EN: «Client Details» левее «Service Location»').toBeLessThan(location);
}

/** Подпись поля прижата к началу строки: HE — правый край подписи у правого края поля, EN — левый у левого. */
async function expectLabelAlign(page: Page, lang: Lang) {
  const label = page.locator('main label').filter({ hasText: new RegExp(`^\\s*${L[lang].clientName}\\s*\\*?\\s*$`) }).first();
  const input = page.getByLabel(new RegExp(`^${L[lang].clientName}`)).first();
  const lb = (await label.boundingBox())!;
  const ib = (await input.boundingBox())!;
  if (lang === 'he') expect(Math.abs(lb.x + lb.width - (ib.x + ib.width)), 'HE: подпись у правого края поля').toBeLessThanOrEqual(12);
  else expect(Math.abs(lb.x - ib.x), 'EN: подпись у левого края поля').toBeLessThanOrEqual(12);
}

test.describe('Jobs screens follow the interface direction (#b809a6)', () => {
  for (const lang of ['he', 'en'] as Lang[]) {
    test(`New Job (${lang.toUpperCase()}): tabs, Client/Service columns and labels go ${lang === 'he' ? 'right-to-left' : 'left-to-right'} #b809a6 @desktop @prod-safe`, async ({ page }) => {
      await useLang(page, lang);
      const smsHits = await blockSmsSending(page);
      try {
        await page.goto('/JobForm?action=new');
        const tabs = page.getByRole('tablist').first().getByRole('tab');
        await expect(tabs).toHaveCount(2);
        await expect(tabs.first()).toHaveText(L[lang].jobInfo);
        // Источник: «מה רצוי» — בעברית הטאבים מתחילים מימין, «פרטי לקוח» מימין, התוויות מיושרות לימין; EN — без изменений.
        expectOrder(await centers([tabs.nth(0), tabs.nth(1)]), lang, 'вкладки New Job');
        await expectColumns(page, lang);
        await expectLabelAlign(page, lang);
      } finally {
        await restoreCompany(page);
      }
      expectNoSmsSent(smsHits);
    });

    test(`Job Details (${lang.toUpperCase()}): tabs from ${L[lang].details} to ${L[lang].equipment} and the Client/Service columns go ${lang === 'he' ? 'right-to-left' : 'left-to-right'} #b809a6 @desktop @prod-safe`, async ({ page }) => {
      await useLang(page, lang);
      const smsHits = await blockSmsSending(page);
      try {
        await page.goto(`/JobDetail?id=${DATA.testJob.id}`);
        await expect(page.getByText(`#${DATA.testJob.code}`).first()).toBeVisible({ timeout: 30_000 });
        const tabs = page.getByRole('tablist').first().getByRole('tab');
        await expect(tabs.first()).toContainText(L[lang].details);
        await expect(tabs.last()).toContainText(L[lang].equipment);
        const n = await tabs.count();
        expect(n, 'вкладки Job Details').toBeGreaterThanOrEqual(5);
        expectOrder(await centers(Array.from({ length: n }, (_, i) => tabs.nth(i))), lang, 'вкладки Job Details');
        await expectColumns(page, lang);
      } finally {
        await restoreCompany(page);
      }
      expectNoSmsSent(smsHits);
    });

    test(`Jobs list (${lang.toUpperCase()}): status tabs and table columns go ${lang === 'he' ? 'right-to-left' : 'left-to-right'} #b809a6 @desktop @prod-safe`, async ({ page }) => {
      await useLang(page, lang);
      const smsHits = await blockSmsSending(page);
      try {
        await openJobsList(page);
        const tabs = page.locator('main').getByRole('tab');
        const n = await tabs.count();
        expect(n, 'вкладки статусов').toBeGreaterThanOrEqual(5);
        // Комментарий программиста: ברשימת Jobs הטאבים והטבלה עוברים לכיוון ימין לשמאל.
        expectOrder(await centers(Array.from({ length: n }, (_, i) => tabs.nth(i))), lang, 'вкладки статусов');
        // Первые три колонки с текстом (номер работы, клиент, теги) в порядке DOM.
        const headers = page.locator('main thead th, main [role="columnheader"]').filter({ hasText: /\S/ });
        await expect(headers.nth(2)).toBeVisible();
        if (lang === 'he') await expect(headers.first()).toHaveText(L.he.jobNumberCol);
        expectOrder(await centers([headers.nth(0), headers.nth(1), headers.nth(2)]), lang, 'колонки таблицы');
      } finally {
        await restoreCompany(page);
      }
      expectNoSmsSent(smsHits);
    });
  }
});
